class _EmbeddedLoader:
    def __init__(self, canonical):
        self._canon = canonical
        self._saved = None
    def create_module(self, spec):
        if spec.name == self._canon:
            return None  # 由导入机器按规范名正常创建
        # 别名：返回规范模块的同一对象（保证类/异常 isinstance 一致）
        c = _il.import_module(self._canon)
        self._saved = {k: getattr(c, k, None)
                       for k in ("__name__", "__package__", "__spec__", "__path__", "__loader__")}
        return c
    def exec_module(self, module):
        if self._saved is not None:          # 别名路径：恢复规范对象身份属性
            for k, v in self._saved.items():
                if v is not None:
                    setattr(module, k, v)
            self._saved = None
            return
        src = _b64.b64decode(_EMBED[self._canon]).decode("utf-8")
        if not getattr(module, "__file__", None):
            module.__file__ = "<embedded:%s>" % self._canon
        code = compile(src, module.__file__, "exec")
        exec(code, module.__dict__)

class _EmbeddedFinder(_iabc.MetaPathFinder):
    def find_spec(self, fullname, path=None, target=None):
        canon = _ALIAS.get(fullname, fullname)
        if canon not in _EMBED:
            return None
        spec = _imach.ModuleSpec(fullname, _EmbeddedLoader(canon),
                                 origin="<embedded:%s>" % canon)
        if canon in _PKGS:
            spec.submodule_search_locations = []
        return spec

_sys.meta_path.insert(0, _EmbeddedFinder())

